function Field({label,name,type="text",value,step,required=false,placeholder,className=""}:{label:string,name:string,type?:string,value?:number|string,step?:string,required?:boolean,placeholder?:string,className?:string}){
  return <label className={"field "+className}><span>{label}</span><Input name={name} type={type} defaultValue={value} step={step} required={required} placeholder={placeholder}/></label>
}
function SelectField({label,name,value,children,className=""}:{label:string,name:string,value?:string,children:any,className?:string}){return <label className={"field "+className}><span>{label}</span><select name={name} defaultValue={value}>{children}</select></label>}
/** Reduz a foto (lado maior 900 px, WebP) e devolve como texto, gravado junto com o produto. Uma foto de celular de 3 MB vira cerca de 60 KB. */
async function compressImage(file:File):Promise<string>{
  if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw new Error("Envie uma foto JPG, PNG ou WebP");
  if(file.size>15_000_000)throw new Error("A foto passa de 15 MB. Escolha uma menor.");
  const bitmap=await createImageBitmap(file),scale=Math.min(1,900/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement("canvas");
  canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);
  canvas.getContext("2d")!.drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();
  return canvas.toDataURL("image/webp",.82);
}
function PageHead({title,description,action}:{title:string,description:string,action?:any}){return <div className="page-head"><div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function Empty({title,description}:{title:string,description:string}){return <div className="empty"><PackageSearch/><strong>{title}</strong><p>{description}</p></div>}
function Stat({label,value,detail,tone="blue",onClick}:{label:string,value:string,detail?:string,tone?:string,onClick?:()=>void}){return <Card className={`stat stat-${tone} ${onClick?"stat-action":""}`} onClick={onClick} onKeyDown={e=>onClick&&["Enter"," "].includes(e.key)&&onClick()} role={onClick?"button":undefined} tabIndex={onClick?0:undefined}><CardContent><span>{label}</span><strong>{value}</strong>{detail&&<small>{detail}</small>}</CardContent></Card>}
