function OrderDetailDialog({order,state,open,onOpenChange,onEdit,onFinancial,save,saving}:{order:any,state:AppState,open:boolean,onOpenChange:(open:boolean)=>void,onEdit:()=>void,onFinancial:()=>void,save:any,saving:boolean}){const productions=(order.productionOrderIds||[]).map((id:string)=>state.productionOrders.find(item=>item.id===id)).filter(Boolean),history=(order.history||[]).slice().reverse();return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="order-detail-dialog"><DialogHeader><DialogTitle>{order.number} · {order.customerName}</DialogTitle><DialogDescription>Criado em {dateLabel(order.createdAt)} · {channelLabel[order.channel as keyof typeof channelLabel]}</DialogDescription></DialogHeader><div className="order-detail-status"><Badge variant={order.status==="concluido"?"secondary":order.status==="cancelado"||order.status==="devolvido"?"destructive":"outline"}>{statusLabel(order.status)}</Badge><span>Pagamento: <b>{statusLabel(order.paymentStatus)}</b></span></div><div className="order-detail-grid"><div><span>Vendedor</span><b>{order.seller||"Não informado"}</b></div><div><span>Origem</span><b>{order.origin||"Não informada"}</b></div><div><span>Forma de pagamento</span><b>{order.paymentMethod||"Não informada"}</b></div><div><span>Entrega</span><b>{order.addressSnapshot||"Não informada"}</b></div></div><div className="section-label"><span>Itens do pedido</span><small>{order.items.reduce((sum:any,item:any)=>sum+item.quantity,0)} unidade(s)</small></div><div className="order-detail-items">{order.items.map((item:any)=><div key={item.id}><span><b>{item.quantity}× {item.productName}</b><small>{item.productSku}</small></span><span>{money(item.unitPrice)} / un</span><b>{money(item.unitPrice*item.quantity-item.discount)}</b></div>)}</div><div className="order-detail-totals"><div><span>Produtos</span><b>{money(order.items.reduce((sum:any,item:any)=>sum+item.unitPrice*item.quantity,0))}</b></div><div><span>Descontos</span><b>− {money(order.discount+order.items.reduce((sum:any,item:any)=>sum+item.discount,0))}</b></div><div><span>Frete cobrado</span><b>{money(order.shippingCharged)}</b></div><div className="order-detail-total"><span>Receita líquida</span><b>{money(order.netRevenue)}</b></div></div>{productions.length>0&&<><div className="section-label"><span>Produção vinculada</span><small>{productions.length} ordem(ns)</small></div><div className="order-production-links">{productions.map((production:any)=><div key={production.id}><b>{production.number}</b><span>{state.products.find(p=>p.id===production.productId)?.name}</span><Badge variant="outline">{statusLabel(production.status)}</Badge></div>)}</div></>}<div className="section-label"><span>Histórico</span><small>{history.length} evento(s)</small></div><div className="order-timeline">{history.map((event:any)=><div key={event.id}><i/><span><b>{statusLabel(event.status)}</b><small>{event.note}</small></span><time>{new Date(event.createdAt).toLocaleString("pt-BR")}</time></div>)}</div>{order.note&&<div className="order-note"><b>Observação</b><p>{order.note}</p></div>}<DialogFooter className="order-detail-actions"><Button variant="outline" type="button" onClick={()=>window.print()}><Printer/>Imprimir</Button>{order.status==="orcamento"&&<Button variant="outline" type="button" onClick={onEdit}><Pencil/>Editar orçamento</Button>}{order.status==="concluido"&&<Button variant="outline" type="button" onClick={onFinancial}><Eye/>Ver resultado</Button>}<OrderActions order={order} state={state} save={save} saving={saving}/><Button type="button" onClick={()=>onOpenChange(false)}>Fechar</Button></DialogFooter></DialogContent></Dialog>}

function OrderEditDialog({order,state,open,onOpenChange,save,saving}:{order:any,state:AppState,open:boolean,onOpenChange:(open:boolean)=>void,save:any,saving:boolean}){return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="order-edit-dialog"><DialogHeader><DialogTitle>Editar {order.number}</DialogTitle><DialogDescription>Enquanto estiver em orçamento, valores comerciais e quantidades podem ser corrigidos.</DialogDescription></DialogHeader><form className="order-edit-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const next=updateDraftOrder(state,order.id,{customerName:s(f,"customerName")||"Consumidor",channel:s(f,"channel") as Channel,seller:s(f,"seller"),discount:n(f,"discount"),shippingCharged:n(f,"shippingCharged"),shippingPaid:n(f,"shippingPaid"),otherCosts:n(f,"otherCosts"),paymentMethod:s(f,"paymentMethod"),origin:s(f,"origin"),campaignId:s(f,"campaignId")||undefined,note:s(f,"note"),items:order.items.map((item:any)=>({id:item.id,quantity:n(f,`quantity-${item.id}`),unitPrice:n(f,`price-${item.id}`),discount:n(f,`item-discount-${item.id}`)}))});if(await save(next,"order-edit")){toast.success("Orçamento atualizado");onOpenChange(false)}}catch(err:any){toast.error(err.message)}}}><div className="form-grid cols-3"><Field label="Cliente" name="customerName" value={order.customerName} required/><SelectField label="Canal" name="channel" value={order.channel}>{Object.entries(channelLabel).map(([value,label])=><option value={value} key={value}>{label}</option>)}</SelectField><Field label="Vendedor" name="seller" value={order.seller}/><Field label="Desconto geral" name="discount" type="number" step=".01" value={order.discount}/><Field label="Frete cobrado" name="shippingCharged" type="number" step=".01" value={order.shippingCharged}/><Field label="Frete pago" name="shippingPaid" type="number" step=".01" value={order.shippingPaid}/><Field label="Outros custos" name="otherCosts" type="number" step=".01" value={order.otherCosts}/><Field label="Forma de pagamento" name="paymentMethod" value={order.paymentMethod}/><Field label="Origem" name="origin" value={order.origin}/><SelectField label="Campanha" name="campaignId" value={order.campaignId||""}><option value="">Nenhuma</option>{state.campaigns.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</SelectField><Field label="Observação" name="note" value={order.note} className="span-2"/></div><div className="section-label"><span>Itens</span><small>Produtos não podem ser substituídos após a criação.</small></div><div className="order-edit-items">{order.items.map((item:any)=><div key={item.id}><span><b>{item.productName}</b><small>{item.productSku}</small></span><Field label="Quantidade" name={`quantity-${item.id}`} type="number" value={item.quantity} required/><Field label="Preço unitário" name={`price-${item.id}`} type="number" step=".01" value={item.unitPrice} required/><Field label="Desconto" name={`item-discount-${item.id}`} type="number" step=".01" value={item.discount}/></div>)}</div><DialogFooter><Button type="button" variant="outline" onClick={()=>onOpenChange(false)}>Cancelar</Button><SaveButton saving={saving}>Salvar orçamento</SaveButton></DialogFooter></form></DialogContent></Dialog>}
function OrderActions({order,state,save,saving}:{order:any,state:AppState,save:any,saving:boolean}){
  const allowed=orderTransitions[order.status]||[],[lossWarning,setLossWarning]=useState<{profit:number;margin:number}|null>(null);
  if(!allowed.length)return <span className="muted">Fluxo encerrado</span>;
  return <details className="inline-details"><summary>Próxima ação</summary><form className="popover-form" onSubmit={async e=>{
    e.preventDefault();
    const f=new FormData(e.currentTarget),status=s(f,"status") as any;
    try{
      let next;
      if(status==="concluido"){
        next=completeSale(state,order.id,n(f,"ads"));
        const result=financialBreakdown(next.orders.find((item:any)=>item.id===order.id));
        if(result.calculatedProfit<0&&!f.get("confirmLoss")){
          setLossWarning({profit:result.calculatedProfit,margin:result.margin});
          toast.error("Revise e confirme a venda com prejuízo antes de concluir.");
          return;
        }
      }else if(status==="devolvido")next=returnSale(state,order.id);else next=transitionOrder(state,order.id,status);
      if(await save(next,"order-status")){
        setLossWarning(null);
        const resulting=next.orders.find((item:any)=>item.id===order.id),message=status==="concluido"?"Venda concluída":status==="devolvido"?"Devolução registrada":status==="aprovado"&&resulting?.status==="pronto"?"Pedido aprovado e estoque separado":status==="aprovado"&&resulting?.status==="producao"?"Pedido aprovado e produção planejada":"Pedido atualizado";
        toast.success(message);
      }
    }catch(err:any){toast.error(err.message)}
  }}><SelectField label="Próxima etapa" name="status" value={allowed[0]}>{allowed.map(x=><option key={x} value={x}>{statusLabel(x)}</option>)}</SelectField>{allowed.includes("concluido")&&<Field label="Custo de anúncios desta venda" name="ads" type="number" step=".01" value={order.advertisingCost||0}/>} {lossWarning&&<div className="sale-loss-warning"><AlertTriangle/><div><b>Esta venda gera prejuízo de {money(Math.abs(lossWarning.profit))}</b><small>Margem estimada: {lossWarning.margin.toFixed(1)}%. Confira custos, frete e anúncios.</small><label><input type="checkbox" name="confirmLoss" required/> Confirmo que desejo concluir esta venda com prejuízo.</label></div></div>}<SaveButton saving={saving}>{lossWarning?"Confirmar prejuízo e concluir":"Confirmar ação"}</SaveButton></form></details>
}

const csvCell=(value:string|number)=>typeof value==="number"?value.toFixed(2).replace(".",","):`"${String(value??"").replaceAll('"','""')}"`;
/** CSV que o Excel em português abre certo: marca UTF-8, ponto e vírgula e vírgula decimal. */
function downloadCsv(filename:string,rows:(string|number)[][]){
  const blob=new Blob(["﻿"+rows.map(row=>row.map(csvCell).join(";")).join("\r\n")],{type:"text/csv;charset=utf-8"}),a=document.createElement("a");
  a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}

const previousMonthOf=(month:string)=>addDays(`${month}-01`,-1).slice(0,7);
const signedMoney=(value:number)=>value<0?`− ${money(Math.abs(value))}`:money(value);

function dueState(dueDate:string,reference:string){
  if(dueDate<reference)return{label:"Vencida",tone:"overdue"};
  if(dueDate===reference)return{label:"Vence hoje",tone:"today"};
  if(dueDate<=addDays(reference,7))return{label:"Vence esta semana",tone:"week"};
  return{label:"Em aberto",tone:"open"};
}

function FinancePage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const reference=today(),[month,setMonth]=useState(localMonth(reference)),[tab,setTab]=useState<"overview"|"payables"|"receivables"|"ledger">("overview"),[payablesView,setPayablesView]=useState<"open"|"month">("open");
  const [expenseDialog,setExpenseDialog]=useState<{id?:string}|null>(null),[payId,setPayId]=useState<string|null>(null),[receiveId,setReceiveId]=useState<string|null>(null),[cancelId,setCancelId]=useState<string|null>(null);
  const months=useMemo(()=>financeMonths(state),[state]),ledger=useMemo(()=>cashLedger(state,month),[state,month]),opening=useMemo(()=>openingBalance(state,month),[state,month]);
  const inflow=cents(ledger.filter(e=>e.kind==="in").reduce((a,e)=>a+e.amount,0)),outflow=cents(ledger.filter(e=>e.kind==="out").reduce((a,e)=>a+e.amount,0)),dre=useMemo(()=>monthlyDre(state,month),[state,month]),previous=useMemo(()=>monthlyDre(state,previousMonthOf(month)),[state,month]),summary=accountsSummary(state,reference);
  const openPayables=state.expenses.filter(e=>e.status==="pendente").sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),monthPayables=state.expenses.filter(e=>localMonth(e.dueDate)===month||localMonth(e.paidAt)===month).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)),payables=payablesView==="open"?openPayables:monthPayables;
  const openReceivables=state.payments.filter(p=>(p.status==="pendente"||p.status==="parcial")&&remainingOf(p)>0).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));
  const cancelTarget=state.expenses.find(e=>e.id===cancelId);
  let running=opening;
  const ledgerRows=ledger.map(entry=>{running=cents(running+(entry.kind==="in"?entry.amount:-entry.amount));return{entry,balance:running}});
  const closing=cents(opening+inflow-outflow);
  const tabs=[["overview","Visão geral"],["payables",`A pagar${openPayables.length?` · ${openPayables.length}`:""}`],["receivables",`A receber${openReceivables.length?` · ${openReceivables.length}`:""}`],["ledger","Extrato"]] as const;
  function exportLedger(){downloadCsv(`extrato-${month}.csv`,[["Data","Descrição","Categoria","Entrada","Saída","Saldo"],["",`Saldo inicial de ${monthLabel(month)}`,"","","",opening],...ledgerRows.map(({entry,balance})=>[dateLabel(entry.date),entry.description,entry.category,entry.kind==="in"?entry.amount:"",entry.kind==="out"?entry.amount:"",balance] as (string|number)[])])}
  function exportDre(){downloadCsv(`resultado-${month}.csv`,[["Linha",monthLabel(month),monthLabel(previousMonthOf(month))],...dre.lines.map(line=>[line.label,line.value,previous.lines.find(x=>x.key===line.key)?.value??0] as (string|number)[])])}
  async function confirmCancel(){if(!cancelTarget)return;try{if(await save(cancelExpense(state,cancelTarget.id),"expense-cancel"))toast.success("Conta cancelada")}catch(error:any){toast.error(error.message)}setCancelId(null)}
  return <>
    <PageHead title="Financeiro" description="Entradas, saídas, contas a pagar e a receber, e o resultado de cada mês." action={<div className="finance-head-actions"><label className="finance-month"><span>Mês</span><select value={month} onChange={e=>setMonth(e.target.value)}>{months.map(m=><option key={m} value={m}>{monthLabel(m)}</option>)}</select></label><Button onClick={()=>setExpenseDialog({})}><Plus/>Nova conta a pagar</Button></div>}/>
    <div className="finance-tabs" role="tablist">{tabs.map(([id,label])=><button key={id} role="tab" aria-selected={tab===id} className={tab===id?"active":""} onClick={()=>setTab(id)}>{label}</button>)}</div>
    {tab==="overview"&&<>
      <div className="stats-grid"><Stat label={`Entradas · ${monthLabel(month)}`} value={money(inflow)} detail="Recebimentos de vendas" tone="green"/><Stat label="Saídas" value={money(outflow)} detail="Contas pagas, compras, frete e anúncios" tone="red"/><Stat label="Saldo do mês" value={signedMoney(cents(inflow-outflow))} detail={`Caixa acumulado ${signedMoney(closing)}`} tone={inflow-outflow>=0?"green":"red"} onClick={()=>setTab("ledger")}/><Stat label="Lucro líquido" value={signedMoney(dre.result)} detail={`${dre.margin.toFixed(1)}% da receita líquida`} tone={dre.result>=0?"violet":"red"}/></div>
      <div className="finance-accounts">
        <button className="finance-account" onClick={()=>setTab("receivables")}><span>A receber</span><b>{money(summary.receivable)}</b><small className={summary.receivableOverdue.length?"tone-overdue":""}>{summary.receivableOverdue.length?`${summary.receivableOverdue.length} vencido${summary.receivableOverdue.length===1?"":"s"}`:"Nada vencido"}</small></button>
        <button className="finance-account" onClick={()=>{setPayablesView("open");setTab("payables")}}><span>A pagar</span><b>{money(summary.payable)}</b><small className={summary.payableOverdue.length?"tone-overdue":summary.payableWeek.length?"tone-week":""}>{summary.payableOverdue.length?`${summary.payableOverdue.length} vencida${summary.payableOverdue.length===1?"":"s"}`:summary.payableWeek.length?`${summary.payableWeek.length} vence${summary.payableWeek.length===1?"":"m"} esta semana`:"Nada vencido"}</small></button>
        <div className="finance-account"><span>Próximos 30 dias</span><b className={summary.next30In-summary.next30Out<0?"tone-overdue":""}>{signedMoney(cents(summary.next30In-summary.next30Out))}</b><small>entra {money(summary.next30In)} · sai {money(summary.next30Out)}</small></div>
      </div>
      <Section title={`Resultado de ${monthLabel(month)}`} description="Vendas concluídas no mês menos os custos delas e as despesas com vencimento no mês.">
        <div className="finance-table dre-table"><DataTable headers={["",monthLabel(month),monthLabel(previousMonthOf(month))]}>{dre.lines.map(line=>{const before=previous.lines.find(x=>x.key===line.key)?.value??0;return <tr key={line.key} className={`dre-${line.kind}`}><td><b>{line.label}</b>{line.detail&&<small>{line.detail}</small>}</td><td>{signedMoney(line.value)}</td><td>{signedMoney(before)}</td></tr>})}</DataTable></div>
        <p className="finance-note">Compras de filamento e manutenção aparecem no extrato, mas não como despesa aqui: já estão no custo das peças vendidas. A categoria Impostos também fica fora, porque o imposto de cada venda já é descontado no pedido. Anúncios informados nos pedidos e despesas de Marketing se somam: lance cada gasto em um lugar só.</p>
        <div className="finance-actions"><Button variant="outline" onClick={exportDre}><Download/>Exportar resultado (CSV)</Button></div>
      </Section>
    </>}
    {tab==="payables"&&<Section title="Contas a pagar" description="Despesas, compras de filamento a prazo e parcelas. Contas recorrentes geram a do mês seguinte quando são pagas.">
      <div className="finance-filter"><button className={payablesView==="open"?"active":""} onClick={()=>setPayablesView("open")}>Em aberto ({openPayables.length})</button><button className={payablesView==="month"?"active":""} onClick={()=>setPayablesView("month")}>{monthLabel(month)} ({monthPayables.length})</button></div>
      {payables.length?<div className="finance-table"><DataTable headers={["Vencimento","Descrição","Valor","Situação",""]}>{payables.map(e=>{const due=e.status==="pendente"?dueState(e.dueDate,reference):null;return <tr key={e.id}><td>{dateLabel(e.dueDate)}</td><td data-label="Descrição"><b>{e.description}</b><small>{[e.category,e.recurring?"Recorrente":"",e.source?.kind==="purchase"?"Compra de filamento":"",e.source?.kind==="maintenance"?"Manutenção":"",e.note].filter(Boolean).join(" · ")}</small></td><td data-label="Valor">{money(e.amount)}</td><td data-label="Situação">{e.status==="pago"?<span className="due-chip due-paid">Paga em {dateLabel(e.paidAt)}</span>:e.status==="cancelado"?<span className="due-chip due-cancelled">Cancelada</span>:<span className={`due-chip due-${due!.tone}`}>{due!.label}</span>}</td><td><div className="row-actions">{e.status==="pendente"&&<Button size="sm" onClick={()=>setPayId(e.id)}>Pagar</Button>}{e.status!=="cancelado"&&<Button size="sm" variant="outline" aria-label={`Editar ${e.description}`} onClick={()=>setExpenseDialog({id:e.id})}><Pencil/></Button>}{e.status==="pendente"&&<Button size="sm" variant="ghost" className="danger-action" onClick={()=>setCancelId(e.id)}>Cancelar</Button>}</div></td></tr>})}</DataTable></div>:<Empty title={payablesView==="open"?"Nenhuma conta em aberto":"Nenhuma conta neste mês"} description="Use Nova conta a pagar para lançar aluguel, energia, assinaturas ou parcelas."/>}
    </Section>}
    {tab==="receivables"&&<Section title="Contas a receber" description="Pedidos ainda não quitados. Marketplaces entram pelo valor do repasse, já sem as taxas.">
      {openReceivables.length?<div className="finance-table"><DataTable headers={["Previsão","Pedido","Esperado","Recebido","Saldo","Situação",""]}>{openReceivables.map(p=>{const order=state.orders.find(o=>o.id===p.orderId),due=dueState(p.dueDate,reference);return <tr key={p.id}><td data-label="Previsão">{dateLabel(p.dueDate)}</td><td data-label="Pedido"><b>{order?.number||"Pedido"}</b><small>{[order?.customerName,order?.channel==="shopee"?"Shopee":order?.channel==="ml"?"Mercado Livre":order?.channel==="direct"?"Venda direta":"",order?statusLabel(order.status):""].filter(Boolean).join(" · ")}</small></td><td data-label="Esperado">{money(p.expected)}</td><td data-label="Recebido">{money(p.received)}</td><td data-label="Saldo"><b>{money(remainingOf(p))}</b></td><td data-label="Situação"><span className={`due-chip due-${p.status==="parcial"&&due.tone==="open"?"partial":due.tone}`}>{p.status==="parcial"&&due.tone==="open"?"Parcial":due.label}</span></td><td><Button size="sm" onClick={()=>setReceiveId(p.id)}>Receber</Button></td></tr>})}</DataTable></div>:<Empty title="Nada a receber" description="Todos os pedidos estão quitados."/>}
    </Section>}
    {tab==="ledger"&&<Section title={`Extrato de ${monthLabel(month)}`} description="Tudo o que entrou e saiu do caixa, pela data do pagamento.">
      <div className="ledger-summary"><span>Saldo inicial <b>{signedMoney(opening)}</b></span><span className="tone-in">Entradas <b>{money(inflow)}</b></span><span className="tone-out">Saídas <b>{money(outflow)}</b></span><span>Saldo final <b>{signedMoney(closing)}</b></span><Button size="sm" variant="outline" onClick={exportLedger}><Download/>Exportar CSV</Button></div>
      {ledgerRows.length?<div className="finance-table"><DataTable headers={["Data","Descrição","Entrada","Saída","Saldo"]}>{ledgerRows.map(({entry,balance})=><tr key={entry.id}><td data-label="Data">{dateLabel(entry.date)}</td><td data-label="Descrição"><b>{entry.description}</b><small>{entry.category}</small></td><td data-label="Entrada" className="tone-in">{entry.kind==="in"?money(entry.amount):""}</td><td data-label="Saída" className="tone-out">{entry.kind==="out"?money(entry.amount):""}</td><td data-label="Saldo">{signedMoney(balance)}</td></tr>)}</DataTable></div>:<Empty title="Sem movimento neste mês" description="Recebimentos e pagamentos aparecem aqui na data em que acontecem."/>}
    </Section>}
    <ExpenseDialog target={expenseDialog} state={state} save={save} saving={saving} onClose={()=>setExpenseDialog(null)}/>
    <PayExpenseDialog expense={state.expenses.find(e=>e.id===payId)} state={state} save={save} saving={saving} onClose={()=>setPayId(null)}/>
    <ReceivePaymentDialog payment={state.payments.find(p=>p.id===receiveId)} state={state} save={save} saving={saving} onClose={()=>setReceiveId(null)}/>
    <AlertDialog open={Boolean(cancelTarget)} onOpenChange={open=>{if(!open)setCancelId(null)}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Cancelar esta conta?</AlertDialogTitle><AlertDialogDescription>{cancelTarget?.description} · {money(cancelTarget?.amount||0)}. Ela sai das contas a pagar e do resultado do mês.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Manter</AlertDialogCancel><Button variant="destructive" onClick={confirmCancel}>Cancelar conta</Button></AlertDialogFooter></AlertDialogContent></AlertDialog>
  </>;
}

function ExpenseDialog({target,state,save,saving,onClose}:{target:{id?:string}|null,state:AppState,save:any,saving:boolean,onClose:()=>void}){
  const expense=target?.id?state.expenses.find(e=>e.id===target.id):undefined,creating=Boolean(target&&!target.id),[paidNow,setPaidNow]=useState(false);
  useEffect(()=>{setPaidNow(false)},[target]);
  const categories=[...new Set([...EXPENSE_CATEGORIES,...state.expenses.map(e=>e.category)])].filter(c=>c!==PURCHASE_CATEGORY&&c!==MAINTENANCE_CATEGORY).sort((a,b)=>a.localeCompare(b,"pt-BR"));
  async function submit(event:any){
    event.preventDefault();const f=new FormData(event.currentTarget);
    try{
      if(creating){const installments=Math.max(1,Math.trunc(n(f,"installments")||1)),next=createExpenses(state,{description:s(f,"description"),category:s(f,"category"),amount:n(f,"amount"),dueDate:s(f,"dueDate"),recurring:Boolean(f.get("recurring")),note:s(f,"note"),paidAt:paidNow?s(f,"paidAt")||today():undefined,installments});if(await save(next,"expense-create")){toast.success(installments>1?`${installments} parcelas lançadas em Contas a pagar`:paidNow?"Despesa lançada como paga":"Conta a pagar criada");onClose()}}
      else if(expense){const next=updateExpense(state,expense.id,{description:s(f,"description"),category:s(f,"category"),amount:n(f,"amount"),dueDate:s(f,"dueDate"),note:s(f,"note"),...(expense.status==="pago"?{paidAt:s(f,"paidAt")}:{recurring:Boolean(f.get("recurring"))})});if(await save(next,"expense-update")){toast.success("Conta atualizada");onClose()}}
    }catch(error:any){toast.error(error.message)}
  }
  return <Dialog open={Boolean(target)} onOpenChange={open=>{if(!open)onClose()}}><DialogContent className="entity-dialog"><DialogHeader><DialogTitle>{creating?"Nova conta a pagar":"Editar conta"}</DialogTitle><DialogDescription>{creating?"Aluguel, energia, assinaturas, ferramentas. Compras de filamento são lançadas em Insumos.":expense?.status==="pago"?"Esta conta já foi paga; ajuste os dados se algo foi lançado errado.":"Os dados valem só para esta conta."}</DialogDescription></DialogHeader>
    {target&&(creating||expense)&&<form key={target.id||"novo"} className="form-grid cols-2" onSubmit={submit}>
      <Field label="Descrição" name="description" value={expense?.description} required className="span-2"/>
      <label className="field"><span>Categoria</span><Input name="category" list="expense-categories" defaultValue={expense?.category||""} placeholder="Ex.: Aluguel" required/><datalist id="expense-categories">{categories.map(c=><option key={c} value={c}/>)}</datalist></label>
      <Field label={creating?"Valor total":"Valor"} name="amount" type="number" step=".01" value={expense?.amount} required/>
      <Field label={creating?"Vencimento (1ª parcela)":"Vencimento"} name="dueDate" type="date" value={expense?.dueDate||today()} required/>
      {creating&&<Field label="Parcelas" name="installments" type="number" value="1"/>}
      {expense?.status==="pago"&&<Field label="Data do pagamento" name="paidAt" type="date" value={localDay(expense.paidAt)} required/>}
      <Field label="Observação" name="note" value={expense?.note} className="span-2"/>
      {(creating||expense?.status==="pendente")&&<label className="check-field"><input type="checkbox" name="recurring" defaultChecked={expense?.recurring}/>Repete todo mês</label>}
      {creating&&<label className="check-field"><input type="checkbox" checked={paidNow} onChange={e=>setPaidNow(e.target.checked)}/>Já está paga</label>}
      {creating&&paidNow&&<Field label="Data do pagamento" name="paidAt" type="date" value={today()}/>}
      <DialogFooter className="span-2"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><SaveButton saving={saving}>{creating?"Lançar":"Salvar"}</SaveButton></DialogFooter>
    </form>}
  </DialogContent></Dialog>;
}

function PayExpenseDialog({expense,state,save,saving,onClose}:{expense?:Expense,state:AppState,save:any,saving:boolean,onClose:()=>void}){
  async function submit(event:any){event.preventDefault();if(!expense)return;const f=new FormData(event.currentTarget);try{const next=payExpense(state,expense.id,{date:s(f,"date"),amount:n(f,"amount")});if(await save(next,"expense-paid")){toast.success(expense.recurring?"Conta paga. A do próximo mês já está em Contas a pagar.":"Conta paga");onClose()}}catch(error:any){toast.error(error.message)}}
  return <Dialog open={Boolean(expense)} onOpenChange={open=>{if(!open)onClose()}}><DialogContent className="entity-dialog"><DialogHeader><DialogTitle>Pagar conta</DialogTitle><DialogDescription>{expense?.description} · vence {dateLabel(expense?.dueDate)}</DialogDescription></DialogHeader>{expense&&<form key={expense.id} className="form-grid cols-2" onSubmit={submit}><Field label="Data do pagamento" name="date" type="date" value={today()} required/><Field label="Valor pago" name="amount" type="number" step=".01" value={expense.amount} required/>{expense.recurring&&<p className="finance-note span-2">Conta recorrente: ao pagar, a de {dateLabel(addMonthsDay(expense.dueDate))} é criada em aberto.</p>}<DialogFooter className="span-2"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><SaveButton saving={saving}>Confirmar pagamento</SaveButton></DialogFooter></form>}</DialogContent></Dialog>;
}

function ReceivePaymentDialog({payment,state,save,saving,onClose}:{payment?:Payment,state:AppState,save:any,saving:boolean,onClose:()=>void}){
  const order=payment&&state.orders.find(o=>o.id===payment.orderId),remaining=payment?remainingOf(payment):0;
  async function submit(event:any){event.preventDefault();if(!payment)return;const f=new FormData(event.currentTarget);try{const next=receivePayment(state,payment.id,{amount:n(f,"amount"),date:s(f,"date"),method:s(f,"method"),note:s(f,"note")}),after=next.payments.find(p=>p.id===payment.id)!;if(await save(next,"payment-received")){toast.success(after.status==="pago"?"Pedido quitado":`Recebimento parcial registrado. Faltam ${money(remainingOf(after))}.`);onClose()}}catch(error:any){toast.error(error.message)}}
  return <Dialog open={Boolean(payment)} onOpenChange={open=>{if(!open)onClose()}}><DialogContent className="entity-dialog"><DialogHeader><DialogTitle>Registrar recebimento</DialogTitle><DialogDescription>{order?.number} · {order?.customerName} · saldo {money(remaining)}</DialogDescription></DialogHeader>{payment&&<form key={payment.id} className="form-grid cols-2" onSubmit={submit}>
    {receiptsOf(payment).length>0&&<div className="span-2 receipt-history">{receiptsOf(payment).map(r=><div key={r.id}><span>{dateLabel(r.date)} · {r.method||"—"}</span><b>{money(r.amount)}</b></div>)}</div>}
    <Field label="Valor recebido" name="amount" type="number" step=".01" value={remaining} required/><Field label="Data" name="date" type="date" value={today()} required/><Field label="Forma" name="method" value={payment.method}/><Field label="Observação" name="note"/>
    <p className="finance-note span-2">Para receber em partes (sinal e restante, por exemplo), informe só o valor que entrou agora.</p>
    <DialogFooter className="span-2"><Button type="button" variant="outline" onClick={onClose}>Cancelar</Button><SaveButton saving={saving}>Registrar</SaveButton></DialogFooter></form>}</DialogContent></Dialog>;
}

const addMonthsDay=(day?:string)=>day?addMonthsFinance(day,1):undefined;

function MarketingPage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const sales=state.orders.filter(o=>o.status==="concluido"),ads=sales.reduce((a,o)=>a+o.advertisingCost,0),attributed=sales.filter(o=>o.campaignId).reduce((a,o)=>a+o.netRevenue,0),newCustomerIds=new Set<string>();let newCount=0;sales.slice().sort((a,b)=>a.createdAt.localeCompare(b.createdAt)).forEach(o=>{if(o.customerId&&!newCustomerIds.has(o.customerId)){newCustomerIds.add(o.customerId);newCount++}});
  return <><PageHead title="Marketing" description="Campanhas, mídia atribuída, CAC e retorno sobre anúncios."/><div className="stats-grid compact"><Stat label="Mídia atribuída" value={money(ads)}/><Stat label="CAC médio" value={money(newCount?ads/newCount:0)}/><Stat label="ROAS atribuído" value={(ads?attributed/ads:0).toFixed(2)+"x"}/></div><Section title="Nova campanha"><form className="form-grid cols-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),campaign={id:uid(),name:s(f,"name"),platform:s(f,"platform"),startDate:s(f,"startDate"),endDate:s(f,"endDate"),investment:n(f,"investment"),objective:s(f,"objective"),target:s(f,"target"),note:s(f,"note"),status:"active" as const};if(await save({...state,campaigns:[...state.campaigns,campaign]},"campaign-create")){toast.success("Campanha cadastrada");e.currentTarget.reset()}}}><Field label="Nome" name="name" required/><Field label="Plataforma" name="platform" required/><Field label="Início" name="startDate" type="date" value={today()}/><Field label="Fim" name="endDate" type="date"/><Field label="Investimento" name="investment" type="number" step=".01"/><Field label="Objetivo" name="objective"/><Field label="Produto ou público" name="target"/><Field label="Observação" name="note"/><SaveButton saving={saving}>Cadastrar campanha</SaveButton></form></Section><div className="campaign-grid">{state.campaigns.map(c=>{const orders=sales.filter(o=>o.campaignId===c.id),revenue=orders.reduce((a,o)=>a+o.netRevenue,0),allocated=orders.reduce((a,o)=>a+o.advertisingCost,0);return <Card key={c.id}><CardContent><div className="campaign-head"><div><small>{c.platform}</small><b>{c.name}</b></div><Badge>{statusLabel(c.status)}</Badge></div><div className="price-grid"><div><span>Investimento</span><b>{money(c.investment)}</b></div><div><span>Atribuído</span><b>{money(allocated)}</b></div><div><span>Receita</span><b>{money(revenue)}</b></div><div><span>ROAS</span><b>{(allocated?revenue/allocated:0).toFixed(2)}x</b></div></div><Progress value={c.investment?Math.min(100,allocated/c.investment*100):0}/><small>{money(Math.max(0,c.investment-allocated))} ainda não atribuído</small></CardContent></Card>})}</div></>
}

function ReportsPage({state}:{state:AppState}){
  const[period,setPeriod]=useState("all"),sales=state.orders.filter(o=>o.status==="concluido"&&(period==="all"||localMonth(o.completedAt||o.createdAt)===period)),expenses=state.expenses.filter(e=>countsInResult(e)&&(period==="all"||localMonth(e.dueDate)===period)),items=sales.flatMap(o=>o.items),byProduct=new Map<string,{name:string,qty:number,revenue:number,profit:number}>();items.forEach(i=>{const x=byProduct.get(i.productId)||{name:i.productName,qty:0,revenue:0,profit:0};x.qty+=i.quantity;x.revenue+=i.revenue;x.profit+=i.profit;byProduct.set(i.productId,x)});const months=[...new Set([...state.orders.map(o=>localMonth(o.completedAt||o.createdAt)),...state.expenses.map(e=>localMonth(e.paidAt||e.dueDate))])].sort().reverse(),revenueTotal=sales.reduce((a,o)=>a+o.netRevenue,0),operationalProfit=sales.reduce((a,o)=>a+o.profit,0),expenseTotal=expenses.reduce((a,e)=>a+e.amount,0),netProfit=operationalProfit-expenseTotal,netMargin=revenueTotal?netProfit/revenueTotal*100:0;
  function csv(){downloadCsv(`relatorio-operacional${period==="all"?"":`-${period}`}.csv`,[["Produto","Quantidade","Receita","Lucro","Margem (%)"],...[...byProduct.values()].map(x=>[x.name,x.qty,x.revenue,x.profit,x.revenue?cents(x.profit/x.revenue*100):0] as (string|number)[])])}
  return <><PageHead title="Relatórios" description="Resultado realizado, produção, estoque e rentabilidade." action={<div className="actions"><select value={period} onChange={e=>setPeriod(e.target.value)}><option value="all">Todo o período</option>{months.map(m=><option key={m} value={m}>{m}</option>)}</select><Button variant="outline" onClick={csv}><Download/>Exportar CSV</Button></div>}/><div className="stats-grid"><Stat label="Receita líquida" value={money(revenueTotal)}/><Stat label="Margem de contribuição" value={money(operationalProfit)} tone="green"/><Stat label="Despesas" value={money(expenseTotal)} tone="red"/><Stat label="Resultado líquido" value={money(netProfit)} detail={`${netMargin.toFixed(1)}% de margem`} tone={netProfit>=0?"green":"red"}/></div><Section title="Rentabilidade por produto">{byProduct.size?<DataTable headers={["Produto","Vendidas","Receita","Lucro","Margem"]}>{[...byProduct.values()].sort((a,b)=>b.profit-a.profit).map(x=><tr key={x.name}><td><b>{x.name}</b></td><td>{x.qty}</td><td>{money(x.revenue)}</td><td className={x.profit>=0?"positive":"negative"}>{money(x.profit)}</td><td>{(x.revenue?x.profit/x.revenue*100:0).toFixed(1)}%</td></tr>)}</DataTable>:<Empty title="Sem dados no período" description="Conclua vendas para gerar os indicadores."/>}</Section></>
}

function MachinesPage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const[createOpen,setCreateOpen]=useState(false);
  return <><PageHead title="Máquinas" description="Capacidade, depreciação, horas e manutenção das impressoras." action={<Button onClick={()=>setCreateOpen(true)}><Plus/>Nova máquina</Button>}/><div className="machine-grid">{state.machines.map(m=>{const usage=m.lifeHours?m.accumulatedHours/m.lifeHours*100:0,maintenance=state.maintenances.filter(x=>x.machineId===m.id);return <Card key={m.id}><CardContent><div className="machine-head"><div className="machine-icon"><Printer/></div><div><b>{m.name}</b><small>{m.model||"Modelo não informado"}</small></div><Badge>{statusLabel(m.status)}</Badge></div><div className="machine-stats"><span>{m.accumulatedHours.toFixed(1)} h utilizadas</span><span>{usage.toFixed(1)}% da vida útil</span></div><Progress value={Math.min(100,usage)}/><div className="product-footer"><span>Depreciação <b>{money(m.lifeHours?m.acquisitionValue/m.lifeHours:0)}/h</b></span><span>Manutenções <b>{maintenance.length}</b></span></div><details className="inline-details"><summary>Registrar manutenção</summary><form className="popover-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),maintenance={id:uid(),machineId:m.id,kind:s(f,"kind") as any,cost:n(f,"cost"),date:s(f,"date")||today(),machineHours:m.accumulatedHours,note:s(f,"note")};if(await save({...state,maintenances:[...state.maintenances,maintenance],machines:state.machines.map(x=>x.id===m.id?{...x,lastMaintenance:maintenance.date}:x),expenses:maintenance.cost>0?[...state.expenses,maintenanceExpense(maintenance,m)]:state.expenses},"maintenance-create"))toast.success(maintenance.cost>0?"Manutenção registrada e saída lançada no caixa":"Manutenção registrada")}}><SelectField label="Tipo" name="kind"><option value="preventiva">Preventiva</option><option value="corretiva">Corretiva</option></SelectField><Field label="Custo" name="cost" type="number" step=".01"/><Field label="Data" name="date" type="date" value={today()}/><Field label="Observação" name="note"/><SaveButton saving={saving}>Registrar</SaveButton></form></details></CardContent></Card>})}</div>{!state.machines.length&&<Empty title="Nenhuma máquina cadastrada" description="Cadastre a primeira impressora para planejar e acompanhar a produção."/>}<Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent className="entity-dialog"><DialogHeader><DialogTitle>Nova máquina</DialogTitle><DialogDescription>Cadastre os dados usados no planejamento e no custo real das produções.</DialogDescription></DialogHeader><form className="dialog-form" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),machine={id:uid(),name:s(f,"name"),model:s(f,"model"),acquisitionValue:n(f,"value"),lifeHours:n(f,"life"),powerKw:n(f,"power"),accumulatedHours:n(f,"hours"),status:"active" as const};if(await save({...state,machines:[...state.machines,machine]},"machine-create")){toast.success("Máquina cadastrada");setCreateOpen(false)}}}><div className="form-grid cols-2"><Field label="Identificação" name="name" required/><Field label="Modelo" name="model"/><Field label="Valor de aquisição" name="value" type="number" step=".01"/><Field label="Vida útil (h)" name="life" type="number"/><Field label="Potência (kW)" name="power" type="number" step=".001"/><Field label="Horas atuais" name="hours" type="number" step=".1"/></div><DialogFooter><Button type="button" variant="outline" onClick={()=>setCreateOpen(false)}>Cancelar</Button><SaveButton saving={saving}>Cadastrar máquina</SaveButton></DialogFooter></form></DialogContent></Dialog></>
}

function SettingsPage({state,save,saving}:{state:AppState,save:any,saving:boolean}){
  const [pendingImport,setPendingImport]=useState<{fileName:string;next:AppState}|null>(null);
  const backupCounts=(value:AppState)=>[["Materiais",value.materials.length],["Compras",value.purchases.length],["Produtos",value.products.length],["Pedidos",value.orders.length],["Clientes",value.customers.length],["Lotes",value.lots.length],["Ordens de produção",value.productionOrders.length],["Despesas",value.expenses.length],["Pagamentos",value.payments.length]] as const;
  const exportBackup=()=>{const a=document.createElement("a"),u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:"application/json"}));a.href=u;a.download=`backup-gestao-3d-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};
  const labels={energyRate:"Tarifa de energia (R$/kWh)",power:"Potência padrão (kW)",manualHourRate:"Valor da hora manual",machineValue:"Valor padrão da máquina",machineLife:"Vida útil padrão (h)",markup:"Markup (%)",taxRate:"Impostos (%)",packagingCost:"Embalagem por unidade",maintenancePercent:"Reserva de manutenção (%)",minPrice:"Preço mínimo",rounding:"Arredondamento",shopeeFee:"Taxa Shopee (%)",shopeeFixed:"Taxa fixa Shopee",mlFee:"Taxa Mercado Livre (%)",mlFixed:"Taxa fixa Mercado Livre",shopeeReleaseDays:"Repasse Shopee (dias após a venda)",mlReleaseDays:"Repasse Mercado Livre (dias após a venda)",openingCash:"Saldo inicial do caixa (R$)"};
  return <><PageHead title="Parâmetros" description="Valores usados apenas em novos cálculos e fichas técnicas."/><Section title="Custos e canais"><form className="form-grid cols-3" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),settings=Object.fromEntries(Object.keys(defaults).map(k=>[k,n(f,k)])) as any;if(await save({...state,settings},"settings-update"))toast.success("Parâmetros atualizados")}}>{Object.keys(defaults).map(k=><Field key={k} label={labels[k]} name={k} type="number" step=".01" value={state.settings[k]}/>) }<SaveButton saving={saving}>Salvar parâmetros</SaveButton></form></Section><Section title="Fornecedores"><form className="form-grid cols-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),supplier={id:uid(),name:s(f,"name"),contact:s(f,"contact"),email:s(f,"email"),note:s(f,"note"),status:"active" as const};if(await save({...state,suppliers:[...state.suppliers,supplier]},"supplier-create")){toast.success("Fornecedor cadastrado");e.currentTarget.reset()}}}><Field label="Nome" name="name" required/><Field label="Contato" name="contact"/><Field label="E-mail" name="email"/><Field label="Observação" name="note"/><SaveButton saving={saving}>Cadastrar fornecedor</SaveButton></form><div className="simple-list">{state.suppliers.map(x=><div key={x.id}><b>{x.name}</b><span>{x.contact||x.email||"Sem contato"}</span></div>)}</div></Section><Section title="Metas mensais"><form className="form-grid cols-4" onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget),goal={id:uid(),month:s(f,"month"),revenue:n(f,"revenue"),profit:n(f,"profit"),margin:n(f,"margin"),production:n(f,"production"),sales:n(f,"sales"),cac:n(f,"cac"),roas:n(f,"roas")};if(await save({...state,goals:[...state.goals.filter(g=>g.month!==goal.month),goal]},"goal-save"))toast.success("Meta salva")}}><Field label="Mês" name="month" type="month" required/><Field label="Faturamento" name="revenue" type="number" step=".01"/><Field label="Lucro" name="profit" type="number" step=".01"/><Field label="Margem (%)" name="margin" type="number" step=".1"/><Field label="Produção" name="production" type="number"/><Field label="Vendas" name="sales" type="number"/><Field label="CAC" name="cac" type="number" step=".01"/><Field label="ROAS" name="roas" type="number" step=".01"/><SaveButton saving={saving}>Salvar meta</SaveButton></form></Section><div className="backup-actions"><Button variant="outline" onClick={exportBackup}><Download/>Exportar backup</Button><label className="upload-button"><Upload/>Importar backup<Input type="file" accept=".json,application/json" onChange={async e=>{const input=e.currentTarget,file=input.files?.[0];input.value="";if(!file)return;try{const raw=JSON.parse(await file.text());if(!raw||typeof raw!=="object"||(!Array.isArray(raw.materials)&&!Array.isArray(raw.filaments)))throw new Error("formato");setPendingImport({fileName:file.name,next:Array.isArray(raw.materials)?hydrateState(raw):migrateLegacy(raw)})}catch{toast.error("Este arquivo não é um backup deste sistema. Escolha o .json gerado em Exportar backup.")}}}/></label></div>
<AlertDialog open={Boolean(pendingImport)} onOpenChange={open=>{if(!open)setPendingImport(null)}}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Substituir todos os dados?</AlertDialogTitle><AlertDialogDescription>Importar {pendingImport?.fileName} apaga os dados atuais e coloca os do arquivo no lugar. Exporte um backup antes, se ainda não exportou.</AlertDialogDescription></AlertDialogHeader>{pendingImport&&<div className="backup-compare"><DataTable headers={["Registro","Atual","No arquivo"]}>{backupCounts(state).map(([label,current],index)=><tr key={label}><td>{label}</td><td>{current}</td><td><b>{backupCounts(pendingImport.next)[index][1]}</b></td></tr>)}</DataTable>{backupCounts(pendingImport.next).every(([,count])=>count===0)&&<p className="backup-empty-warning">O arquivo não tem nenhum registro. Importar deixa o sistema vazio.</p>}</div>}<AlertDialogFooter><Button variant="outline" onClick={exportBackup}><Download/>Exportar backup atual</Button><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction onClick={async()=>{const next=pendingImport?.next;setPendingImport(null);if(next&&await save(next,"backup-import"))toast.success("Backup importado")}}>Substituir dados</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></>
}
